<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;
class HeatmapRun extends Model{use HasFactory;protected $fillable=['survey_id','floor_plan_id','generated_by','metric','algorithm','algorithm_version','status','grid_width','grid_height','power','weak_threshold','source_point_count','coverage_percent','estimated_area_percent','mean_absolute_error','root_mean_square_error','parameters','source_measurement_ids','grid_data','confidence_grid','error_message','generated_at'];protected function casts():array{return ['parameters'=>'array','source_measurement_ids'=>'array','grid_data'=>'array','confidence_grid'=>'array','generated_at'=>'datetime','power'=>'decimal:3','coverage_percent'=>'decimal:3','estimated_area_percent'=>'decimal:3'];}public function survey(){return $this->belongsTo(Survey::class);}public function floorPlan(){return $this->belongsTo(FloorPlan::class);}public function generator(){return $this->belongsTo(User::class,'generated_by');}}
